(() => {
  const g = __rhf.game;
  g.state.settings.autoQuality = false;
  g.setQuality('low');
  g.bears.directorT = 1e9;
  g.env.timeScale = 0;
  g.hud.firstShown = -1000;
  g.hud.hint('', 0);
  __rhf.god(true);
  g.state.gear.camera = true;
  window.__until = async (fn, ms = 240000) => {
    const t0 = performance.now();
    while (performance.now() - t0 < ms) {
      const r = fn();
      if (r) return r;
      await new Promise((q) => setTimeout(q, 200));
    }
    return null;
  };
  // deep forest round Salmon Bend, the same spots every run
  let seed = 11;
  const rand = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);
  const W = g.world;
  const b = W.place('bend');
  const fo = (x, z) => W.forest[W.cellIndex(x, z)];
  window.__spots = [];
  for (let k = 0; k < 20000 && __spots.length < 3; k++) {
    const x = b.x + (rand() - 0.5) * 500;
    const z = b.z + (rand() - 0.5) * 500;
    if (!W.inBounds(x, z, 80) || W.waterAt(x, z) || W.slopeAt(x, z) > 0.2 || fo(x, z) < 100) continue;
    __spots.push({ x, z });
  }
  return 'deep forest spots: ' + __spots.map((s) => s.x.toFixed(0) + ',' + s.z.toFixed(0)).join(' | ');
})()

(() => {
  const g = __rhf.game;
  const W = g.world;
  const s = __spots[0];
  g.env.setTime(20.8);
  g.player.place(s.x, s.z, 0);
  g.player.tool = 'camera';
  g.viewmodel.setTool('none');
  // the trees round you: spruce (a cone to the ground) or broadleaf
  let cone = 0;
  let round = 0;
  for (const c of g.colliders.circlesNear(s.x, s.z, 30)) {
    if (c.tag !== 'tree' || (c.x - s.x) ** 2 + (c.z - s.z) ** 2 > 900) continue;
    if (c.cone) cone++;
    else if (c.cr) round++;
  }
  g.bigfoot.active = false;
  let ok = false;
  for (let k = 0; k < 24 && !ok; k++) {
    g.player.yaw = k * 0.6;
    ok = g.bigfoot.spawn();
  }
  return 'spot 1: within 30 m ' + cone + ' spruce and ' + round + ' broadleaf trees; Bigfoot ' + (ok ? 'stepped out ' + Math.hypot(g.bigfoot.pos.x - s.x, g.bigfoot.pos.z - s.z).toFixed(0) + ' m away' : 'found no clear spot');
})()

(async () => {
  const g = __rhf.game;
  const B = g.bigfoot;
  const P = g.player;
  if (!B.active) return 'nothing to aim at';
  // hold him where he stepped out, so the look and the picture show the
  // same moment (he strolls, and the test renderer is slow)
  if (!B.held) {
    // his update with no time passing: he stands, and his figure stays where he is
    const go = B.update.bind(B);
    B.update = () => go(0);
    B.held = true;
  }
  while (g.photo.zoom !== 8) g.photo.zoomIndex = (g.photo.zoomIndex + 1) % 4;
  const aim = () => {
    const dx = B.pos.x - P.pos.x;
    const dz = B.pos.z - P.pos.z;
    P.yaw = Math.atan2(-dx, -dz);
    P.pitch = Math.atan2(B.pos.y + 1.4 - (P.pos.y + 1.7), Math.hypot(dx, dz));
  };
  aim();
  const t0 = g.time;
  await __until(() => {
    aim();
    return g.time - t0 > 2;
  }, 180000);
  aim();
  const f = g.photo.evaluate();
  return 'through the lens: ' + (f ? f.id + ' ' + f.stars + ' stars (' + f.seen + ' of 3 points clear), fills ' + (f.frac * 100).toFixed(0) + '%' : 'nothing');
})()

(() => {
  // how much of him the frame really shows: paint him a flat magenta, count
  // his pixels in the real view and with everything else hidden
  const g = __rhf.game;
  const B = g.bigfoot;
  if (!B.active) return 'no Bigfoot to measure';
  const R = g.renderer;
  const gl = R.getContext();
  const w = R.domElement.width;
  const h = R.domElement.height;
  const swaps = [];
  B.group.traverse((o) => {
    if (!o.isMesh) return;
    const m = o.material.clone();
    m.onBeforeCompile = () => {};
    m.vertexColors = false;
    if (m.color) m.color.setRGB(1, 0, 1);
    if (m.emissive) m.emissive.setRGB(1, 0, 1);
    m.map = null;
    m.fog = false;
    m.toneMapped = false;
    m.needsUpdate = true;
    swaps.push([o, o.material]);
    o.material = m;
  });
  const count = () => {
    R.setRenderTarget(null);
    R.clear(true, true, true);
    R.render(g.scene, g.camera);
    const px = new Uint8Array(w * h * 4);
    gl.readPixels(0, 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, px);
    let n = 0;
    for (let i = 0; i < px.length; i += 4) if (px[i] > 140 && px[i + 1] < 100 && px[i + 2] > 140) n++;
    return n;
  };
  const seen = count();
  const hid = [];
  for (const c of g.scene.children) if (c !== B.group && c.visible && !c.isLight) { hid.push(c); c.visible = false; }
  const alone = count();
  hid.forEach((c) => (c.visible = true));
  for (const [o, m] of swaps) o.material = m;
  return 'in the frame ' + seen + ' of his ' + alone + ' pixels show (' + (alone ? Math.min(100, Math.round((seen / alone) * 100)) : 0) + ' %)';
})()

